// Merge per-item: keep access_token, pull eset_email from corresponding tenant
const itemIndex = $itemIndex;
const tenant = $('Get active tenants').all()[itemIndex].json;
return {
  json: {
    eset_email: tenant.eset_email,
    access_token: $json.access_token || '',
    region: tenant.region || 'us',
    status_code: $json.status_code || null,
  }
};

// Tag devices array with eset_email for downstream processing
const email = $('Merge token+email').item.json.eset_email;
return {
  json: {
    eset_email: email,
    devices: $json.devices || [],
  }
};

// Item: { access_token, ..., $('Get active tenants').item.eset_email }
// Pero el item actual ya tiene el access_token + el eset_email del tenant.
// Necesitamos: para cada item (= 1 tenant response), expandir devices[].
const VIRT_MACS = ['00:09:0F','00:15:5D','00:50:56','00:0C:29','00:1C:42','52:54:00','08:00:27'];
const GENERIC_BIOS = ['microsoft','hpe','hp ','asus','dell','gigabyte','lenovo','system manufacturer','default string','to be filled'];
const normMac = raw => { if(!raw) return null; const c=String(raw).replace(/[-:.]/g,'').toUpperCase(); if(!/^[0-9A-F]{12}$/.test(c)||c==='000000000000') return null; const f=c.match(/.{2}/g).join(':'); return VIRT_MACS.some(p=>f.startsWith(p))?null:f; };
const normDiskSerial = raw => { if(!raw) return null; const s=String(raw).trim(); if(s.length<6||/^([0-9A-Za-z])\1+$/i.test(s)) return null; return s.toUpperCase(); };
const normBios = raw => { if(!raw) return null; const s=String(raw).trim(); if(s.length<8||s.includes(' ')) return null; return GENERIC_BIOS.some(p=>s.toLowerCase().startsWith(p))?null:s; };
const pickDiskGb = hd => { if(!hd||hd.length===0) return null; let b=0; for(const d of hd){const c=Number(d.capacityBytes); if(!isNaN(c)&&c>0&&c<100e12) b+=c;} return b>0?Math.round(b/1e9):null; };
const inferStatus = s => { const u=String(s||'').toUpperCase(); if(u==='OK'||u.endsWith('_OK')) return 'Protected'; if(u.includes('REQUIRED')) return 'Critical'; if(u.includes('RECOMMENDED')) return 'Warning'; return u||'Unknown'; };

// $input.all() = todos los items (uno por tenant, cada uno con `devices[]` posiblemente)
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const email = j.eset_email;
  const devices = j.devices || [];
  for (const d of devices) {
    const hp = d.hardwareProfiles?.[0];
    out.push({ json: {
      uuid: d.uuid,
      hostname: d.displayName ?? null,
      mac: hp?.networkAdapters?.[0]?.macAddress ? normMac(hp.networkAdapters[0].macAddress) : null,
      bios_serial: hp?.bios?.serialNumber ? normBios(hp.bios.serialNumber) : null,
      disk_serial: hp?.hardDrives?.[0]?.serialNumber ? normDiskSerial(hp.hardDrives[0].serialNumber) : null,
      hardware_uuid: hp?.bios?.uuid ? String(hp.bios.uuid).trim() : null,
      eset_email: email,
      account_id: null,
      display_name: d.displayName ?? null,
      last_seen: d.lastSyncTime ?? null,
      status: inferStatus(d.functionalityStatus),
      threats: d.functionalityProblemCount ?? 0,
      products: (d.deployedComponents ?? []).map(c => c.displayName).filter(Boolean),
      os: d.operatingSystem?.displayName ?? null,
      os_version: d.operatingSystem?.version?.name ?? null,
      cpu: hp?.processors?.[0]?.caption?.trim() ?? null,
      disk_gb: pickDiskGb(hp?.hardDrives),
    }});
  }
}
console.log(`Total devices mapped: ${out.length}`);
return out;

// Collect all rows into single rows_json
const rows = $input.all().map(i => i.json);
console.log(`Aggregate: ${rows.length} rows`);
return [{ json: { rows_json: JSON.stringify(rows), count: rows.length } }];
